FACTORS = [
    {'name': 'MA (Moving Average)', 'formula': 'MA(Close, N)', '原理': 'N天收盘价的平均值，是最基础的趋势指标。价格在均线上方说明偏强，均线向上倾斜说明趋势向上。', '如何使用': '均线交叉策略：短期均线上穿长期均线买入。适合趋势明显的市场。', '注意事项': '在震荡市中频繁交叉信号噪音多；参数选择决定灵敏度（短期=灵敏但假信号多）。'},
    {'name': 'EMA (Exponential Moving Average)', 'formula': 'EMA(Close, N)', '原理': '指数加权均线，越近期的价格权重越大，对价格变化的反应比MA更快。', '如何使用': 'EMA12/EMA26交叉判断短期趋势；MACD的核心组成部分。', '注意事项': '比MA更灵敏，但假信号也更多。参数越小越灵敏。'},
    {'name': 'MACD', 'formula': 'MACD = EMA(Close, 12) - EMA(Close, 26)', '原理': '快线EMA12减慢线EMA26，衡量短期和中期趋势的差异。MACD柱状图反映动量变化。', '如何使用': 'MACD线上穿信号线（金叉）买入，线下穿（死叉）卖出。零轴上方偏多。', '注意事项': 'MACD是滞后指标，在盘整行情中容易反复交叉产生假信号。'},
    {'name': 'RSI (Relative Strength Index)', 'formula': 'RSI = 100 - 100/(1 + RS), RS = N天平均涨幅/平均跌幅', '原理': '衡量价格上涨和下跌的相对强度，范围0-100。>70超买（可能反转下跌），<30超卖（可能反弹）。', '如何使用': 'RSI<30寻找超卖买入机会；RSI>70寻找超买卖出机会；也可以配合趋势线使用。', '注意事项': '强趋势中RSI可以长时间维持在超买/超卖区域不止损。参数14是标准值。'},
    {'name': 'KDJ', 'formula': 'RSV = (Close - LLV(Low, N)) / (HHV(High, N) - LLV(Low, N)) * 100', '原理': '随机指标，衡量当前价格在最近N天高低范围的相对位置。K和D在0-100之间波动。', '如何使用': 'K线从下上穿D线买入（金叉）；K线从上跌破D线卖出（死叉）。J值>100超买，<0超卖。', '注意事项': '参数N通常用9；震荡市中效果好，趋势市中需要配合其他指标。'},
    {'name': 'BOLL (Bollinger Bands)', 'formula': '中轨=MA(Close, N), 上轨=中轨+2*StdDev, 下轨=中轨-2*StdDev', '原理': '由中轨（均线）和上下两条轨道组成。轨道宽度随波动率变化自动调整（波动率越高轨道越宽）。', '如何使用': '价格触及下轨时可能超卖买入；触及上轨时可能超买卖出。布林带收口提示突破方向。', '注意事项': '参数N通常20，标准差倍数通常2。趋势行情中价格可以沿着轨道运行很久不止损。'},
    {'name': 'ATR (Average True Range)', 'formula': 'TR = max(High-Low, |High-PrevClose|, |Low-PrevClose|); ATR = MA(TR, N)', '原理': '衡量市场波动率的指标，取True Range的N日均值。ATR越大说明市场越动荡。', '如何使用': '用于设置动态止损：止损位=入场价 - N*ATR。', '注意事项': 'ATR本身不指示方向，只衡量波动幅度。常作为辅助指标配合其他策略使用。'},
    {'name': 'ADX (Average Directional Index)', 'formula': 'ADX = N日DMI趋势强度均值', '原理': '衡量趋势强度的指标，范围0-100。ADX>25说明趋势强，ADX<20说明趋势弱（震荡）。', '如何使用': 'ADX上升时顺势交易（趋势市场）；ADX下降时使用均值回归策略（震荡市场）。', '注意事项': 'ADX不指示方向（上涨还是下跌），只说明趋势有多强。需要结合+DI/-DI判断方向。'},
    {'name': 'CCI (Commodity Channel Index)', 'formula': 'CCI = (TypicalPrice - MA(TypicalPrice, N)) / (0.015 * MeanDeviation)', '原理': '衡量价格偏离其统计均值的程度。围绕0波动，>100超买，<-100超卖。', '如何使用': 'CCI从下方上穿-100买入（超卖区域）；CCI从上方下穿+100卖出（超买区域）。', '注意事项': '适合商品期货；对趋势股票可能长时间维持超买/超卖。参数N通常20。'},
    {'name': 'WR (Williams %R)', 'formula': 'WR = (HHV(High, N) - Close) / (HHV(High, N) - LLV(Low, N)) * -100', '原理': '威廉指标，与RSI类似但方向相反。<-80超卖，>-20超买。', '如何使用': 'WR上穿-80从超卖转强买入；WR下穿-20从超买转弱卖出。', '注意事项': '参数通常14；负数越大（WR越负）说明越超卖。'},
    {'name': 'OBV (On-Balance Volume)', 'formula': '如果Close>PrevClose则OBV+=Volume，否则OBV-=Volume', '原理': '累计成交量指标，假设成交量放大时价格朝着同一方向移动。OBV上升说明资金流入，下降说明资金流出。', '如何使用': 'OBV与价格出现背离时预警趋势反转（如价格创新高但OBV未创新高=可能见顶）。', '注意事项': 'OBV是领先指标但信号较模糊，常用于确认趋势而非独立产生信号。'},
    {'name': 'VR (Volume Ratio)', 'formula': 'VR = N日内上涨日成交量之和 / N日内下跌日成交量之和 * 100', '原理': '量比指标，衡量上涨日和下跌日的成交量对比。VR>300说明市场过热，VR<70说明市场低迷。', '如何使用': 'VR在低位时买入（市场低迷往往是底部区域）；VR在高位时注意获利了结。', '注意事项': '参数N通常取26天（约一个月），需结合大势判断。'},
    {'name': 'DMI (Directional Movement Index)', 'formula': '+DI = 上升动向强度, -DI = 下降动向强度, ADX = 趋势强度', '原理': 'DMI包含方向指标+DI/-DI和趋势强度ADX三个部分。+DI上穿-DI是多头信号，-DI上穿+DI是空头信号。', '如何使用': '+DI > -DI 且 ADX 上升：顺势做多；-DI > +DI 且 ADX 上升：顺势做空。', '注意事项': '参数N通常14；DMI最擅长在趋势明显的市场中顺势交易。'},
    {'name': 'TRIX (Triple EMA)', 'formula': '对收盘价连续做三次EMA然后取变化率', '原理': '三重指数平滑平均线，消除噪音，对趋势变化的反应灵敏且过滤假信号。', '如何使用': 'TRIX上穿0轴买入，下穿0轴卖出；配合移动平均线使用效果更好。', '注意事项': '参数N通常12；适合中长线趋势交易，短线噪音较多。'},
    {'name': 'DPO (Detrended Price Oscillator)', 'formula': 'DPO = Close - MA(Close, N/2+1)的偏移均线', '原理': '去除趋势的价格摆动指标，用于识别价格的中期周期和超买超卖。', '如何使用': 'DPO在0轴上方说明价格偏强；在0轴下方说明价格偏弱。可配合BOLL使用。', '注意事项': 'DPO不指示趋势方向，只识别价格与均线的偏离程度。'},
    {'name': 'KAMA (Kaufman Adaptive Moving Average)', 'formula': 'KAMA = 前日KAMA + SF * (价格变化 - 前日KAMA) * 适应系数', '原理': '自适应均线，根据市场波动率自动调整平滑系数。波动大时均线变缓（减少噪音），波动小时均线变快（跟进价格）。', '如何使用': '类似MA使用，但KAMA在震荡时噪音更少。适合希望均线更聪明的交易者。', '注意事项': '参数通常N=10, 2, 30；比普通EMA反应更平滑但计算复杂。'},
]
